  "input": {
    "text": "我爷爷奶奶听力稍弱，得走近点说。家里已经知道伴侣要来，我们还准备了茶叶和一盒水果。那问候、介绍和递礼物具体怎么排？",
    "language": "Chinese",
    "voice_setting": {
      "voice_id": "qwen3-profile-b91c855040fc40d7",
      "seed": 1164719321,
